import { revalidateTag, unstable_cache } from 'next/cache'
import { after } from 'next/server'

interface Product {
  id: string
  name: string
  price: number
  inventory: number
}

interface Catalog {
  version: number
  products: Product[]
}

let catalogState: Catalog = {
  version: 1,
  products: [
    { id: 'sku-1', name: 'Wireless Headphones', price: 199, inventory: 50 },
    { id: 'sku-2', name: 'USB-C Cable', price: 19, inventory: 200 },
    { id: 'sku-3', name: 'Mechanical Keyboard', price: 149, inventory: 30 },
  ],
}

async function fetchLatestCatalogFromUpstream(): Promise<Catalog> {
  await new Promise((resolve) => setTimeout(resolve, 2000))

  catalogState = {
    version: catalogState.version + 1,
    products: catalogState.products.map((product) => ({
      ...product,
      price: product.price + Math.floor(Math.random() * 10) - 5,
      inventory: Math.max(0, product.inventory + Math.floor(Math.random() * 20) - 10),
    })),
  }

  return catalogState
}

const getCachedCatalog = unstable_cache(
  async (): Promise<Catalog> => catalogState,
  ['catalog'],
  { tags: ['products'] }
)

export default async function AdminCatalogPage() {
  const catalog = await getCachedCatalog()

  async function syncCatalog() {
    'use server'

    after(async () => {
      await fetchLatestCatalogFromUpstream()
      revalidateTag('products')
    })
  }

  return (
    <main style={{ padding: '2rem', fontFamily: 'system-ui, sans-serif' }}>
      <h1>Admin Product Catalog</h1>

      <form action={syncCatalog} style={{ marginBottom: '1.5rem' }}>
        <button type="submit" style={{ padding: '0.5rem 1rem' }}>
          Sync latest catalog
        </button>
        <p style={{ fontSize: '0.875rem', color: '#666' }}>
          Syncs run in the background. You can keep working while catalog data refreshes.
        </p>
      </form>

      <p>Catalog version: {catalog.version}</p>

      <table style={{ width: '100%', borderCollapse: 'collapse', marginTop: '1rem' }}>
        <thead>
          <tr style={{ textAlign: 'left', borderBottom: '2px solid #ccc' }}>
            <th>SKU</th>
            <th>Name</th>
            <th>Price</th>
            <th>Inventory</th>
          </tr>
        </thead>
        <tbody>
          {catalog.products.map((product) => (
            <tr key={product.id} style={{ borderBottom: '1px solid #eee' }}>
              <td>{product.id}</td>
              <td>{product.name}</td>
              <td>${product.price}</td>
              <td>{product.inventory}</td>
            </tr>
          ))}
        </tbody>
      </table>
    </main>
  )
}

